public class Mux {
    static double choose(int n, int k) {
        double r = 1;
        for (int i = 1; i <= k; i++) r = r * (n - k + i) / i;
        return r;
    }

    public static void main(String[] args) {
        int users = 35, capacityUsers = 10;
        double p = 0.10;
        double tail = 0;
        for (int k = capacityUsers + 1; k <= users; k++)
            tail += choose(users, k) * Math.pow(p, k) * Math.pow(1 - p, users - k);
        System.out.printf("circuit switching supports %d users%n", capacityUsers);
        System.out.printf("packet switching with %d users: P(more than %d active) = %.6f%n",
                users, capacityUsers, tail);
        double circuitSeconds = 640_000 / 64_000.0 + 0.5;
        System.out.printf("640 kbit file, 64 kbit/s circuit, 0.5 s setup: %.1f s%n",
                circuitSeconds);
    }
}

import java.net.*;
import java.util.*;

public class Ifaces {
    public static void main(String[] args) throws Exception {
        for (NetworkInterface nif : Collections.list(NetworkInterface.getNetworkInterfaces())) {
            byte[] mac = nif.getHardwareAddress();
            String m = mac == null ? "none" : HexFormat.ofDelimiter(":").formatHex(mac);
            System.out.printf("%-5s up=%b loopback=%b mtu=%d mac=%s%n",
                nif.getName(), nif.isUp(), nif.isLoopback(), nif.getMTU(), m);
            for (InterfaceAddress ia : nif.getInterfaceAddresses())
                System.out.printf("      %s/%d%n", ia.getAddress().getHostAddress(),
                    ia.getNetworkPrefixLength());
        }
    }
}

public class Delay {
    public static void main(String[] args) {
        double L = 12_000;                       // packet length in bits (1500 bytes)
        for (double R : new double[]{10e6, 100e6, 1e9})
            System.out.printf("R=%8.0f Mbit/s  d_trans=%.4f ms%n", R / 1e6, L / R * 1000);
        double prop = 2_000_000 / 2.0e8;         // 2000 km at 2 x 10^8 m/s
        System.out.printf("d_prop (2000 km) = %.1f ms%n", prop * 1000);
        double bdp = 100e6 * 0.040;
        System.out.printf("BDP = %.0f bits = %.0f bytes%n", bdp, bdp / 8);
        System.out.printf("store-and-forward, 3 links, 1 packet: %.1f ms%n", 3 * L / 10e6 * 1000);
        System.out.printf("8 MB over a 2 Mbit/s bottleneck: %.0f s%n", 8e6 * 8 / 2e6);
    }
}

import java.util.*;

public class SwitchSim {
    static final int PORTS = 4;
    static final Map<String, Integer> table = new LinkedHashMap<>();

    static void frame(int inPort, String src, String dst) {
        table.put(src, inPort);                       // learn: source address seen on ingress port
        String action;
        if (dst.equals("ff:ff:ff:ff:ff:ff") || !table.containsKey(dst)) {
            StringBuilder out = new StringBuilder();
            for (int p = 1; p <= PORTS; p++) if (p != inPort) out.append(p).append(' ');
            String kind = dst.startsWith("ff") ? "broadcast" : "unknown unicast, flood";
            action = kind + " to ports " + out.toString().trim();
        } else if (table.get(dst) == inPort) {
            action = "filter (destination on the same port)";
        } else {
            action = "forward to port " + table.get(dst);
        }
        System.out.printf("port %d  %s -> %s : %s%n", inPort, src, dst, action);
        System.out.println("   table = " + table);
    }

    public static void main(String[] args) {
        String a = "aa:00:00:00:00:01", b = "aa:00:00:00:00:02", c = "aa:00:00:00:00:03";
        frame(1, a, b);
        frame(2, b, a);
        frame(3, c, "ff:ff:ff:ff:ff:ff");
        frame(1, a, c);
        frame(1, a, "aa:00:00:00:00:09");
    }
}

import java.util.Random;

public class Csma {
    public static void main(String[] args) {
        Random rnd = new Random(42);
        int cw = 16, rounds = 200_000;
        for (int n : new int[]{2, 5, 10, 20}) {
            int collisions = 0;
            for (int r = 0; r < rounds; r++) {
                int min = Integer.MAX_VALUE, countMin = 0;
                for (int s = 0; s < n; s++) {
                    int b = rnd.nextInt(cw);
                    if (b < min) { min = b; countMin = 1; }
                    else if (b == min) countMin++;
                }
                if (countMin > 1) collisions++;
            }
            System.out.printf("stations=%2d  P(collision at first attempt, CW=%d) = %.3f%n",
                    n, cw, collisions / (double) rounds);
        }
    }
}
